 485: function parseAttrs(tag) {
 486:   const attrs = {};
 487:   const re = /([^\s=<>/"']+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
 488:   const inner = tag.replace(/^<\s*[\w-]+/, '').replace(/\/?>$/, '');
 489:   for (const m of inner.matchAll(re)) attrs[m[1].toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';
 490:   return attrs;
 491: }
